#ifndef slic3r_GUI_SendTimelapseGate_hpp_
#define slic3r_GUI_SendTimelapseGate_hpp_

// Whether the Bambu send dialog offers "Timelapse" for a plate's G-code
// (SelectMachineDialog::is_show_timelapse): not for G-code written by this program's line
// (OrcaSlicer, Snapmaker Orca) before 2.2.0. Read from the header's "; generated by" line only.
// No wx: the unit tests read it from a string.

#include <istream>
#include <string>

namespace Slic3r { namespace GUI {

// True unless the header names OrcaSlicer or Snapmaker Orca at a version below min_version.
// Only the first lines are read (the header), never the whole file.
bool timelapse_allowed_for_gcode(std::istream& gcode, const std::string& min_version = "2.2.0");

}} // namespace Slic3r::GUI

#endif
